const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=x=>x===null?'Not measured':`${(100*x).toFixed(1)}%`;
const number=x=>x===null?'Not measured':x.toFixed(3);
function riskChart(evaluation) {
  const curve=evaluation.riskCoverage.curve;
  // Fixed numeric coordinates only; no imported markup enters the chart.
  const points=curve.map(p=>`${40+p.coverage*420},${210-p.risk*180}`).join(' ');
  return `<svg viewBox="0 0 500 255" role="img" aria-label="Risk versus coverage on known development images; lower error at useful coverage is better" style="width:100%;max-width:650px"><path d="M40 30V210H460" fill="none" stroke="currentColor"/><polyline points="${points}" fill="none" stroke="#28694e" stroke-width="3"/><g fill="currentColor" font-size="13"><text x="4" y="35">100%</text><text x="12" y="212">0%</text><text x="38" y="230">0%</text><text x="430" y="230">100%</text><text x="160" y="250">Accepted coverage</text><text x="40" y="18">Prediction error among accepted cases</text></g></svg>`;
}
export function reliabilityDashboard(report) {
  const rows=report.experiments.flatMap(experiment=>Object.entries(experiment.evaluations).map(([domain,e])=>`<tr><td>${esc(experiment.calibrationDomain)} → ${esc(domain)}</td><td>${esc(experiment.profile.method)}</td><td>${e.knownCount}</td><td>${pct(e.conformalCoverage)}</td><td>${number(e.averageSetSize)}</td><td>${number(e.before.ece)} → ${number(e.after.ece)}</td><td>${number(e.before.nll)} → ${number(e.after.nll)}</td></tr>`)).join('');
  const historical=report.historical;
  return `<div class="page-heading"><div><div class="eyebrow">RELIABILITY LAB</div><h1>Evidence before guidance.</h1><p>Existing V3 weights · LAC and APS · Nominal set coverage ${pct(1-report.alpha)}</p></div><span class="tag amber">DEVELOPMENT ONLY</span></div>
    <div class="notice"><div><strong>These are reused development examples.</strong><p>The model was selected using these images. Partitioning their saved logits now does not create an independent test. No live guidance policy has been enabled.</p></div></div>
    <section class="panel panel-padding"><h2>The three decisions</h2><div class="project-grid"><div><h3>Retake the image</h3><p>Failed exposure/detail checks. A better photo may help.</p></div><div><h3>Expert verification</h3><p>Unknown, mismatched or unvalidated predictions. Current real-image predictions remain in this category.</p></div><div><h3>Basic guidance</h3><p>Requires a matching independently evaluated policy and a curated reference. Not enabled for the existing models.</p></div></div></section>
    <section class="panel panel-padding"><h2>Calibration and prediction sets</h2><p>Temperature is fitted on one partition; set thresholds on another. Measurements below use the remaining audit partition. A source-to-field mismatch has no automatic conformal guarantee.</p><div class="table-wrap"><table><thead><tr><th>Calibration → evaluation</th><th>Method</th><th>Known images</th><th>Set coverage</th><th>Mean labels</th><th>ECE before → after</th><th>NLL before → after</th></tr></thead><tbody>${rows}</tbody></table></div></section>
    ${report.experiments.filter(x=>x.profile.method==='LAC').map(experiment=>{
      const e=experiment.evaluations.PlantDoc;
      return `<section class="panel panel-padding"><h2>${esc(experiment.calibrationDomain)} calibration → field-style development audit</h2>${riskChart(e)}<p>Known images: ${e.knownCount} · AURC: ${number(e.riskCoverage.aurc)}. The curve ranks known images by maximum probability; ties are accepted together.</p><div class="table-wrap"><table><thead><tr><th>Candidate policy</th><th>Known accepted</th><th>Coverage</th><th>Accepted error</th><th>Unsupported accepted</th></tr></thead><tbody>${[['Confidence threshold',e.confidencePolicy],['Confidence + singleton set',e.singletonPolicy]].map(([name,p])=>`<tr><td>${name}</td><td>${p.knownAccepted}/${e.knownCount}</td><td>${pct(p.knownCoverage)}</td><td>${pct(p.acceptedKnownRisk)}</td><td>${p.unknownAccepted}/${p.unknownCount}</td></tr>`).join('')}</tbody></table></div><p>Unknown-detection AUROC: MSP ${number(e.unknownAUROC.msp)}, maximum logit ${number(e.unknownAUROC.maxLogit)}, energy ${number(e.unknownAUROC.energy)}. Larger AUROC is better; these unknown condition types were seen during development.</p></section>`;
    }).join('')}
    <section class="panel panel-padding"><h2>Historical external benchmark remains unchanged</h2><p>${historical.knownCount} known images · Accuracy ${pct(historical.accuracy)} · Accepted ${historical.accepted}/${historical.knownCount} (${pct(historical.coverage)}) · Unsupported accepted ${historical.unknownAccepted}/${historical.unknownCount}.</p><p>${esc(historical.note)}</p></section>
    <section class="panel panel-padding"><h2>Evidence limits</h2><ul>${report.limitations.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><a class="btn secondary" href="research/reliability-audit.json" download>Download complete measurements</a></section>`;
}
